// A. Shared Library Creation (Position Independent Code)
// Enables efficient mapping of text segment (sharing)
// -fPIC (GCC/Clang): Mandatory for memory sharing
gcc -c -fPIC utility.c -o utility.o

// -shared: Links objects into dynamic library (.so)
gcc -shared utility.o -o libutility.so

// Linking executable against shared library
// ld.so handles linking at runtime (Load Time)
gcc main.c -L. -lutility -o app

// B. Runtime Dynamic Linking (dlopen)
// Used when library dependency is unknown until runtime
// Crucial for plugins or hot-swapping code without restarts

void* handle = dlopen("libplugin.so", RTLD_NOW);
if (!handle) { /* log error */ }

// Get function symbol address (GOT lookup)
double (*exec)(double);
exec = (double (*)(double))dlsym(handle, "process_data");

double r = exec(1.0);
dlclose(handle);
